head.script:
scwin.checkVal = function() {
    var ret = true;
    var itemArr1 = WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1___selectbox_col1').itemArr;
    var itemArr2 = selectbox1.itemArr;
    if (itemArr1.length !== itemArr2.length) {
        return "length diff";
    }
    for (var i = 0; i < itemArr1.length; i++) {
        if (itemArr1[i].label !== itemArr2[i].label || itemArr1[i].value !== itemArr2[i].value) {
            ret = itemArr1[i].label + "," + itemArr2[i].label + "@@" + itemArr1[i].value + "," + itemArr2[i].value;
            break;
        }
    }
    return ret;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Design 탭에 gridview 탭 선택해서 col1 의 inputType 부분을 확인한다.
    //On the Design tab, select the gridview tab and check the inputType part of col1.
    //Verify 1. inputType = 'select'
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tabs2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').getAttribute(dataInputType) == 'select'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Veryfi 4. 3번째 select 탭의 Select 처럼 정상적으로 바인딩되서 리스트가 보여진다. (그전버전에서는 비활성화 된 탭에 있는 경우 바인딩 되지 않아서 리스트가 보이지 않았음)
    //The list is displayed as it is normally bound as in the Select on the third select tab. (In previous versions, if you were on a disabled tab, the list was not visible because it was not bound.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    dataList1.setData(["aa", "11", "bb", "22"]);
    window.arr = [];
    for (var ix = 0; ix < 20; ix++) {
        arr.push("hello" + ix);
    }
    dataList2.setData(arr);
    selectbox1.setNodeSet("data:dataList1", "label", "value");
    if (!tabControl1.isLoaded(1)) {
        var promiseObj = tabControl1.activateTab(1);
        if (promiseObj && typeof promiseObj.then === "function") {
            promiseObj.then(function(s,f){
                gridView1.setColumnNodeSet("col1", "data:dataList1", "label", "value");
            });
        } else {
            gridView1.setColumnNodeSet("col1", "data:dataList1", "label", "value");
        }
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 30-Jan-2018
    //End unitTest
    window.dataInputType = WebSquare.util.getDataPrefix("inputtype");
}
